/*

Attempting to invent a new(?) technique for traversing voxel grids, 
with a fixed step guaranteed to visit all voxels in the ray's
direction exactly once. 

The step distance s for a normalized direction vector d is

    s = 1.0 / (|d.x| + |d.y| ... |d.n|),

(should theoretically be extensible to 3D 
but I haven't gotten that to work yet) 

This works perfectly in 2D when position is grid- or half grid-aligned,
but otherwise not. 

However, it seems that there is always an offset, 
for any position and direction, that can be applied to
the marched distance so that everything lines up. 

I haven't yet found the formula to calculate that offset.

Calculating actual distance travelled is trivial,
just snap the fixed-step distance to the closest multiple
of the delta distance.

*/

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 col = vec3(0);
    float scale = 8.;
    vec2 mouse = scale * iMouse.xy / iResolution.y;    
    vec2 mouse2 = scale * abs(iMouse.zw) / iResolution.y;
    vec2 uv = scale * fragCoord / iResolution.y;
    vec2 cellUv = fract(uv);
    vec2 cell = floor(scale * fragCoord / iResolution.y);

    // Ray origin and direction
    vec2 pos = length(iMouse.xy) > 10. ? mouse2 : vec2(scale / 2.);
    vec2 dir = length(iMouse.xy) > 10. ? normalize(mouse - mouse2): vec2(cos(iTime), sin(iTime));

    // Change to false to see issues with non-grid aligned ray origin.
    if (true) {
        vec2 grid_aligned = round(pos);
        vec2 dual_aligned = floor(pos) + .5;
        if (length(pos - grid_aligned) < length(pos - dual_aligned)) {
            pos = grid_aligned;
        } else {
            pos = dual_aligned;
        }
    }

    // Grid lines and circle at ray origin
    vec2 gridLines = step(.97, cellUv);
    col = mix(col, vec3(.2, .3, .2), max(gridLines.x, gridLines.y));
    col = mix(col, vec3(0., 1., 0.), 1. - step(0.1, length(uv - pos)));

    vec2 d_dist = 1. / abs(dir);   
    vec2 side_d = (sign(-dir) * (floor(pos) - pos) + (sign(-dir) * .5) + .5) * d_dist; 

    // Step size
    float s = 1. / (abs(dir.x) + abs(dir.y));

    vec2 c_offset_a = step(.0, dir) - fract(pos);
    vec2 c_offset_b = 1. - step(.0, dir) - fract(pos);

    // Offset would be calculated here if I knew how.
    // One idea to be tested: Four different offsets, 
    // based on what corner the ray is facing.
    float offset = 0.0;
    //corner_dist = dot(dir, c_offset_a);
    //corner_dist = 2. * length(pos - round(pos)) * corner_dist;  
    //corner_dist = -length(round(pos) - pos) / s;
    //corner_dist = .0;

    // Visualizing offset
    vec2 offset_pos = pos + dir * offset;
    float alpha = .1 / (dot(dir, uv - offset_pos)) * (1. - smoothstep(0., 3., length(uv - offset_pos)));
    col = mix(col, vec3(1., 0., 0.), .3 * alpha);    

    const float n = 22.; // number of sample points to show
    for (float i = 1.; i < n; i++) {
        vec2 step_pos = pos + (i * s + offset - .0001) * dir;
        // Draw sample point
        col = mix(col, vec3(1., 0., 0.), 1. - step(.1, length(uv - step_pos)));
        // Fill in sampled grid cell
        col = mix(col, vec3(.3, .6, .4), .3 * float(cell == floor(step_pos)));
    }
    fragColor = vec4(col,1.);
}
